<?php declare(strict_types=1); ?><!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#172033"><title>Rafay POS</title><style>
:root{--primary:#172033;--accent:#e74c3c;--bg:#f4f6f9;--card:#fff;--text:#1f2937;--muted:#6b7280;--border:#e5e7eb;--ok:#166534;--warn:#9a3412;--danger:#991b1b}*{box-sizing:border-box}body{margin:0;font-family:Inter,system-ui,Segoe UI,sans-serif;background:var(--bg);color:var(--text)}button,input,select,textarea{font:inherit}.hidden{display:none!important}.top{background:var(--primary);color:#fff;padding:14px 20px;display:flex;justify-content:space-between;align-items:center;gap:15px;position:sticky;top:0;z-index:5}.brand h1{margin:0;font-size:21px}.brand small{opacity:.75}.wrap{max-width:1500px;margin:auto;padding:20px}.bar{display:flex;gap:10px;flex-wrap:wrap;margin-bottom:15px;align-items:center}.input,.select,.textarea{padding:11px 12px;border:1px solid var(--border);border-radius:9px;background:#fff}.textarea{min-height:90px;resize:vertical}.search{flex:1;min-width:220px}.btn{border:0;border-radius:9px;padding:10px 14px;cursor:pointer;font-weight:700}.btn:disabled{opacity:.55;cursor:not-allowed}.primary{background:var(--accent);color:#fff}.secondary{background:#fff;border:1px solid var(--border)}.danger{background:#b91c1c;color:#fff}.success{background:#166534;color:#fff}.layout{display:grid;grid-template-columns:minmax(0,2fr) minmax(340px,1fr);gap:18px}.card{background:var(--card);border:1px solid var(--border);border-radius:14px;padding:16px;box-shadow:0 4px 15px #00000008}.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(190px,1fr));gap:12px}.product{padding:14px;border:1px solid var(--border);border-radius:12px;cursor:pointer;background:#fff;position:relative;transition:.12s}.product:hover{border-color:var(--accent);transform:translateY(-1px)}.product.disabled{opacity:.5;cursor:not-allowed}.badge{font-size:11px;padding:3px 7px;border-radius:999px;background:#dcfce7;color:#166534}.badge.low{background:#ffedd5;color:#9a3412}.badge.off{background:#fee2e2;color:#991b1b}.cart-row{display:grid;grid-template-columns:1fr auto;gap:10px;padding:12px 0;border-bottom:1px solid var(--border)}.qty{display:flex;align-items:center;gap:6px}.qty button{width:30px;height:30px;border:1px solid var(--border);background:#fff;border-radius:6px;cursor:pointer}.totals{display:grid;gap:8px;margin-top:12px}.total{font-size:22px;font-weight:800}.modal{position:fixed;inset:0;background:#0008;display:flex;align-items:center;justify-content:center;padding:15px;z-index:20}.modal>div{width:min(760px,100%);max-height:94vh;overflow:auto;background:#fff;border-radius:16px;padding:20px}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:10px}.form-grid .full{grid-column:1/-1}.invoice{font-family:Arial,sans-serif;max-width:520px;margin:auto;border:1px solid #ddd;padding:22px;color:#222;background:#fff}.invoice header{text-align:center;border-bottom:2px dashed #999;padding-bottom:12px}.invoice table{width:100%;border-collapse:collapse;margin:15px 0}.invoice th,.invoice td{padding:7px 0;border-bottom:1px solid #eee;text-align:left}.invoice th:last-child,.invoice td:last-child{text-align:right}.row{display:flex;justify-content:space-between;gap:10px}.table{width:100%;border-collapse:collapse}.table th,.table td{padding:10px 8px;border-bottom:1px solid var(--border);text-align:left;vertical-align:top}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}.stat strong{display:block;font-size:24px}.login{min-height:100vh;display:grid;place-items:center;padding:20px}.login .card{width:min(430px,100%)}.tabs{display:flex;gap:8px;overflow:auto;margin-bottom:15px}.tab.active{background:var(--primary);color:#fff}.notice{padding:10px;border-radius:8px;background:#fff7ed;color:var(--warn);margin-bottom:12px}.muted{color:var(--muted)}.pill{display:inline-block;padding:4px 8px;border-radius:999px;font-size:12px;background:#eef2ff}.danger-text{color:var(--danger)}.ok-text{color:var(--ok)}.two{display:grid;grid-template-columns:1fr 1fr;gap:12px}.kpi-list{display:grid;gap:8px}.kpi-list .row{padding:8px 0;border-bottom:1px solid var(--border)}
@media(max-width:950px){.layout{grid-template-columns:1fr}.stats{grid-template-columns:1fr 1fr}.two{grid-template-columns:1fr}}@media(max-width:600px){.form-grid{grid-template-columns:1fr}.form-grid .full{grid-column:auto}.stats{grid-template-columns:1fr}.wrap{padding:12px}.top{padding:12px}.hide-mobile{display:none}.table{font-size:13px}}
@media print{body{background:#fff}.no-print,.modal .no-print{display:none!important}.modal{position:static;background:none;padding:0}.modal>div{width:100%;max-height:none;overflow:visible;padding:0}.invoice{border:0;max-width:none}.print-58 .invoice{width:58mm;font-size:10px}.print-80 .invoice{width:80mm;font-size:11px}@page{margin:4mm}}
</style></head><body>
<div id="loginView" class="login"><div class="card"><h1>Rafay POS</h1><p class="muted">Standalone point of sale system</p><form id="loginForm"><input class="input" style="width:100%;margin-bottom:10px" id="email" type="email" autocomplete="username" placeholder="Email" required><input class="input" style="width:100%;margin-bottom:10px" id="password" type="password" autocomplete="current-password" placeholder="Password" required><button id="loginBtn" class="btn primary" style="width:100%">Sign in</button></form><p id="loginMsg" class="danger-text"></p><small>Use PHP 8+ and MySQL/MariaDB. See README.md for installation.</small></div></div>
<div id="app" class="hidden"><div class="top"><div class="brand"><h1 id="shopName">Rafay POS</h1><small id="shopSlogan">Point of Sale</small></div><div><span id="userName"></span> <button class="btn secondary" onclick="logout()">Logout</button></div></div><div class="wrap">
<div id="superBar" class="bar hidden"><select id="shopSelect" class="select"></select><button class="btn secondary" onclick="loadAll()">Refresh</button><button class="btn secondary" onclick="openShopModal()">+ Shop</button><a id="backupBtn" class="btn secondary" href="api.php?action=backup">Backup DB</a></div>
<div class="tabs"><button class="btn secondary tab active" data-tab="pos">POS</button><button class="btn secondary tab" data-tab="invoices">Invoices</button><button class="btn secondary tab" data-tab="products">Products</button><button class="btn secondary tab" data-tab="customers">Customers</button><button class="btn secondary tab" data-tab="users">Users</button><button class="btn secondary tab" data-tab="reports">Reports</button><button class="btn secondary tab" data-tab="audit">Audit</button><button class="btn secondary tab" data-tab="dashboard">Dashboard</button><button class="btn secondary tab" data-tab="settings">Settings</button></div>
<section id="tab-pos"><div class="bar"><input id="productSearch" class="input search" placeholder="Search product, category or SKU/barcode"><button class="btn secondary" onclick="clearCart()">Clear cart</button></div><div class="layout"><div class="card"><h2>Products</h2><div id="productsGrid" class="grid"></div></div><div class="card"><h2>Current Order</h2><div id="cart"></div><div class="totals"><div class="row"><span>Subtotal</span><strong id="subtotal">Rs. 0.00</strong></div><div class="row"><label>Discount</label><input id="discount" class="input" style="width:140px" type="number" min="0" step="0.01" value="0"></div><div class="row"><label>Tax</label><input id="tax" class="input" style="width:140px" type="number" min="0" step="0.01" value="0"></div><div class="row total"><span>Total</span><span id="total">Rs. 0.00</span></div><button class="btn primary" onclick="openCheckout()">Checkout</button></div></div></div></section>
<section id="tab-invoices" class="hidden"><div class="card"><div class="bar"><input id="invoiceSearch" class="input search" placeholder="Search invoice, customer or status"><button class="btn secondary" onclick="loadInvoices()">Refresh</button></div><div style="overflow:auto"><table class="table"><thead><tr><th>Invoice</th><th>Customer</th><th>Total</th><th>Payment</th><th>Status</th><th>Date</th><th></th></tr></thead><tbody id="invoiceTable"></tbody></table></div></div></section>
<section id="tab-products" class="hidden"><div class="card"><div class="bar"><button id="addProductBtn" class="btn primary" onclick="openProduct()">+ Product</button><input id="productAdminSearch" class="input search" placeholder="Filter products"><button class="btn secondary" onclick="loadProducts()">Refresh</button></div><div style="overflow:auto"><table class="table"><thead><tr><th>Name</th><th>SKU</th><th>Category</th><th>Price</th><th>Cost</th><th>Stock</th><th>Status</th><th></th></tr></thead><tbody id="productTable"></tbody></table></div></div></section>
<section id="tab-customers" class="hidden"><div class="card"><h2>Customers</h2><div style="overflow:auto"><table class="table"><thead><tr><th>Name</th><th>Phone</th><th>Address</th><th>Created</th></tr></thead><tbody id="customerTable"></tbody></table></div></div></section>
<section id="tab-users" class="hidden"><div class="card"><div class="bar"><h2 style="margin-right:auto">Shop Users</h2><button id="addUserBtn" class="btn primary" onclick="openUser()">+ User</button><button class="btn secondary" onclick="loadUsers()">Refresh</button></div><div style="overflow:auto"><table class="table"><thead><tr><th>Name</th><th>Email</th><th>Role</th><th>Active</th><th>Last login</th><th></th></tr></thead><tbody id="userTable"></tbody></table></div></div></section>
<section id="tab-reports" class="hidden"><div class="card"><div class="bar"><input id="reportFrom" class="input" type="date"><input id="reportTo" class="input" type="date"><button class="btn primary" onclick="loadReports()">Run report</button><button class="btn secondary" onclick="exportInvoicesCsv()">Export invoices CSV</button></div><div class="stats"><div class="card stat"><small>Revenue</small><strong id="rRevenue">0</strong></div><div class="card stat"><small>Invoices</small><strong id="rInvoices">0</strong></div><div class="card stat"><small>Tax</small><strong id="rTax">0</strong></div><div class="card stat"><small>Discounts</small><strong id="rDiscounts">0</strong></div></div><div class="two" style="margin-top:12px"><div class="card"><h3>Top products</h3><div id="topProducts"></div></div><div class="card"><h3>Payment breakdown</h3><div id="paymentBreakdown"></div></div></div></div></section>
<section id="tab-audit" class="hidden"><div class="card"><div class="bar"><h2 style="margin-right:auto">Audit log</h2><button class="btn secondary" onclick="loadAudit()">Refresh</button></div><div style="overflow:auto"><table class="table"><thead><tr><th>Time</th><th>User</th><th>Action</th><th>Entity</th><th>Details</th><th>IP</th></tr></thead><tbody id="auditTable"></tbody></table></div></div></section>
<section id="tab-dashboard" class="hidden"><div class="stats"><div class="card stat"><small>Today revenue</small><strong id="sToday">0</strong><span id="sTodayCount"></span></div><div class="card stat"><small>7-day revenue</small><strong id="sWeek">0</strong><span id="sWeekCount"></span></div><div class="card stat"><small>Products</small><strong id="sProducts">0</strong></div><div class="card stat"><small>Low stock</small><strong id="sLow">0</strong></div></div><div class="card" style="margin-top:12px"><h3>Today's payment methods</h3><div id="dashPayments" class="kpi-list"></div></div></section>
<section id="tab-settings" class="hidden"><div class="two"><div class="card"><h2>Account security</h2><form id="passwordForm"><input id="oldPassword" class="input" style="width:100%;margin-bottom:8px" type="password" placeholder="Current password"><input id="newPassword" class="input" style="width:100%;margin-bottom:8px" type="password" placeholder="New password (10+ characters)"><button class="btn primary">Change password</button></form><p id="passwordMsg"></p></div><div class="card"><h2>Current shop</h2><div id="shopInfo"></div></div></div></section>
</div></div>
<div id="checkoutModal" class="modal hidden"><div><h2>Checkout</h2><div class="form-grid"><input id="custName" class="input" placeholder="Customer name"><input id="custPhone" class="input" placeholder="Phone"><input id="custAddress" class="input full" placeholder="Address"><select id="payment" class="select"><option value="cash">Cash</option><option value="card">Card</option><option value="bank">Bank</option><option value="other">Other</option></select><input id="received" class="input" type="number" min="0" step="0.01" placeholder="Amount received"></div><p>Total: <strong id="checkoutTotal">0</strong></p><p>Change: <strong id="changeDue">0</strong></p><div class="bar"><button id="saleBtn" class="btn primary" onclick="completeSale()">Complete Sale</button><button class="btn secondary" onclick="closeModal('checkoutModal')">Cancel</button></div><p id="checkoutMsg" class="danger-text"></p></div></div>
<div id="productModal" class="modal hidden"><div><h2 id="productModalTitle">Product</h2><input type="hidden" id="pId"><div class="form-grid"><input id="pName" class="input" placeholder="Name"><input id="pSku" class="input" placeholder="SKU / Barcode"><input id="pCategory" class="input" placeholder="Category"><input id="pDesc" class="input full" placeholder="Description"><input id="pCost" class="input" type="number" min="0" step="0.01" placeholder="Cost price"><input id="pPrice" class="input" type="number" min="0" step="0.01" placeholder="Selling price"><input id="pStock" class="input" type="number" min="0" step="1" placeholder="Stock"><input id="pLow" class="input" type="number" min="0" step="1" value="5" placeholder="Low stock threshold"><label><input id="pActive" type="checkbox" checked> Active / sellable</label></div><div class="bar"><button class="btn primary" onclick="saveProduct()">Save</button><button class="btn secondary" onclick="closeModal('productModal')">Cancel</button></div><p id="productMsg" class="danger-text"></p></div></div>
<div id="userModal" class="modal hidden"><div><h2 id="userModalTitle">User</h2><input type="hidden" id="uId"><div class="form-grid"><input id="uName" class="input" placeholder="Name"><input id="uEmail" class="input" type="email" placeholder="Email"><select id="uRole" class="select"><option value="cashier">Cashier</option><option value="shop_admin">Shop Admin</option></select><input id="uPassword" class="input" type="password" placeholder="Password (10+ chars for new/change)"><label><input id="uActive" type="checkbox" checked> Active</label></div><div class="bar"><button class="btn primary" onclick="saveUser()">Save</button><button class="btn secondary" onclick="closeModal('userModal')">Cancel</button></div><p id="userMsg" class="danger-text"></p></div></div>
<div id="shopModal" class="modal hidden"><div><h2 id="shopModalTitle">Create Shop</h2><input type="hidden" id="sId"><div class="form-grid"><input id="sName" class="input" placeholder="Shop name"><input id="sCurrency" class="input" value="Rs." placeholder="Currency"><input id="sPhone" class="input" placeholder="Phone"><input id="sPlanExpiry" class="input" type="date" placeholder="Plan expiry"><input id="sSlogan" class="input full" placeholder="Slogan"><input id="sAddress" class="input full" placeholder="Address"><select id="sPlan" class="select"><option value="starter">Starter</option><option value="professional">Professional</option><option value="business">Business</option><option value="custom">Custom</option></select><select id="sStatus" class="select"><option value="active">Active</option><option value="suspended">Suspended</option></select><input id="sAdminName" class="input" placeholder="Shop admin name (new shop)"><input id="sAdminEmail" class="input" type="email" placeholder="Shop admin email (new shop)"><input id="sAdminPassword" class="input" type="password" placeholder="Admin password (10+ chars)"></div><p class="muted">For an existing shop, leave admin fields blank and save only shop settings.</p><div class="bar"><button class="btn primary" onclick="saveShop()">Save shop</button><button class="btn secondary" onclick="closeModal('shopModal')">Cancel</button></div><p id="shopMsg" class="danger-text"></p></div></div>
<div id="invoiceModal" class="modal hidden"><div><div class="bar no-print"><button class="btn primary" onclick="printInvoice('print-80')">Print 80mm</button><button class="btn secondary" onclick="printInvoice('print-58')">Print 58mm</button><button class="btn secondary" onclick="downloadInvoice()">Download TXT</button><button id="cancelInvoiceBtn" class="btn danger hidden" onclick="changeInvoiceStatus('cancel')">Cancel invoice</button><button id="refundInvoiceBtn" class="btn danger hidden" onclick="changeInvoiceStatus('refund')">Refund invoice</button><button class="btn secondary" onclick="closeModal('invoiceModal')">Close</button></div><div id="invoicePrint" class="invoice"></div></div></div>
<script>
const state={user:null,csrf:'',shop:null,shops:[],products:[],cart:[],invoices:[],customers:[],users:[],currentInvoice:null};
const $=id=>document.getElementById(id); const esc=v=>String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
function num(v){const n=Number(v);return Number.isFinite(n)?n:0} function money(v){return `${esc(state.shop?.currency||'Rs.')} ${num(v).toFixed(2)}`}
async function api(action,opts={}){let url='api.php?action='+encodeURIComponent(action)+(opts.params?'&'+new URLSearchParams(opts.params):'');const headers={'Accept':'application/json'};if(opts.body){headers['Content-Type']='application/json';headers['X-CSRF-Token']=state.csrf}const r=await fetch(url,{method:opts.method||'GET',headers,body:opts.body?JSON.stringify(opts.body):undefined,credentials:'same-origin'});const ct=r.headers.get('content-type')||'';let d=ct.includes('application/json')?await r.json():{error:await r.text()};if(r.status===401){state.user=null;showLogin()}if(!r.ok)throw new Error(d.error||'Request failed');return d}
async function boot(){try{const d=await api('me');state.csrf=d.csrf||'';if(d.user){state.user=d.user;showApp();await loadAll()}else showLogin()}catch(e){showLogin()}}
function showLogin(){$('loginView').classList.remove('hidden');$('app').classList.add('hidden')}function showApp(){$('loginView').classList.add('hidden');$('app').classList.remove('hidden');$('userName').textContent=`${state.user.name} • ${state.user.role}`;$('superBar').classList.toggle('hidden',state.user.role!=='super_admin');$('addProductBtn').classList.toggle('hidden',state.user.role==='cashier');$('addUserBtn').classList.toggle('hidden',state.user.role==='cashier')}
$('loginForm').addEventListener('submit',async e=>{e.preventDefault();$('loginMsg').textContent='';$('loginBtn').disabled=true;try{const d=await api('login',{method:'POST',body:{email:$('email').value,password:$('password').value}});state.user=d.user;state.csrf=d.csrf;showApp();await loadAll()}catch(err){$('loginMsg').textContent=err.message}finally{$('loginBtn').disabled=false}});
async function logout(){try{await api('logout')}finally{location.reload()}}
async function loadAll(){if(state.user.role==='super_admin'){const s=await api('shops');state.shops=s.shops;renderShopSelect();if(!state.shop&&state.shops[0]){const active=state.shops.find(x=>x.status==='active');if(active){await api('set_shop',{method:'POST',body:{shop_id:Number(active.id)}})}}}const sh=await api('shop');state.shop=sh.shop;$('shopName').textContent=state.shop.name;$('shopSlogan').textContent=state.shop.slogan||'Point of Sale';$('shopInfo').innerHTML=`<p><b>${esc(state.shop.name)}</b></p><p>${esc(state.shop.address||'')}</p><p>${esc(state.shop.phone||'')}</p><p>Plan: <span class="pill">${esc(state.shop.plan)}</span> ${state.shop.plan_expires_at?`expires ${esc(state.shop.plan_expires_at)}`:''}</p>`;renderShopSelect();await Promise.all([loadProducts(),loadInvoices(),loadCustomers(),loadDashboard(),state.user.role==='cashier'?Promise.resolve():loadUsers(),state.user.role==='cashier'?Promise.resolve():loadAudit()]);renderCart()}
function renderShopSelect(){if(state.user.role!=='super_admin')return;$('shopSelect').innerHTML=state.shops.filter(s=>s.status==='active').map(s=>`<option value="${Number(s.id)}">${esc(s.name)} • ${esc(s.plan)}</option>`).join('');$('shopSelect').value=state.shop?.id||''}
$('shopSelect').addEventListener('change',async()=>{await api('set_shop',{method:'POST',body:{shop_id:Number($('shopSelect').value)}});state.shop=null;state.cart=[];await loadAll()});
async function loadProducts(){const d=await api('products');state.products=d.products;renderProducts();renderProductTable()}
function renderProducts(){const q=$('productSearch').value.toLowerCase();const arr=state.products.filter(p=>Number(p.active)===1&&(p.name+' '+(p.category||'')+' '+(p.sku||'')).toLowerCase().includes(q));$('productsGrid').innerHTML=arr.map(p=>{const stock=Number(p.stock);return `<div class="product ${stock<1?'disabled':''}" onclick="addToCart(${Number(p.id)})"><span class="badge ${stock<1?'off':stock<=Number(p.low_stock_threshold)?'low':''}">${stock<1?'Out of stock':stock+' in stock'}</span><h3>${esc(p.name)}</h3><small>${esc(p.category||'')} ${p.sku?'• '+esc(p.sku):''}</small><p>${esc(p.description||'')}</p><strong>${money(p.selling_price)}</strong></div>`}).join('')||'<p>No products found.</p>'}
function addToCart(id){const p=state.products.find(x=>Number(x.id)===id);if(!p||Number(p.active)!==1||Number(p.stock)<1)return alert('Out of stock');let x=state.cart.find(i=>i.product_id===id);if(x){if(x.quantity>=Number(p.stock))return alert('Stock limit reached');x.quantity++}else state.cart.push({product_id:id,name:p.name,sku:p.sku,unit_price:Number(p.selling_price),quantity:1,stock:Number(p.stock)});renderCart()}
function renderCart(){const sub=state.cart.reduce((a,i)=>a+i.unit_price*i.quantity,0);$('cart').innerHTML=state.cart.map((i,n)=>`<div class="cart-row"><div><strong>${esc(i.name)}</strong><br><small>${money(i.unit_price)} each</small></div><div class="qty"><button onclick="changeQty(${n},-1)">−</button><span>${i.quantity}</span><button onclick="changeQty(${n},1)">+</button><button onclick="removeCart(${n})">×</button></div></div>`).join('')||'<p class="muted">Cart is empty.</p>';$('subtotal').textContent=money(sub);updateTotals()}
function changeQty(n,d){const i=state.cart[n];if(!i)return;const next=i.quantity+d;if(next<1)return removeCart(n);if(next>i.stock)return alert('Stock limit reached');i.quantity=next;renderCart()}function removeCart(n){state.cart.splice(n,1);renderCart()}function clearCart(){state.cart=[];renderCart()}
function totals(){const sub=round2(state.cart.reduce((a,i)=>a+i.unit_price*i.quantity,0));const dis=Math.min(Math.max(0,num($('discount').value)),sub);const tax=Math.max(0,num($('tax').value));return{sub,dis:round2(dis),tax:round2(tax),total:round2(Math.max(0,sub-dis+tax))}}function round2(n){return Math.round((n+Number.EPSILON)*100)/100}
function updateTotals(){const t=totals();$('total').textContent=money(t.total);$('checkoutTotal').textContent=money(t.total);const r=Math.max(0,num($('received').value));$('changeDue').textContent=money(Math.max(0,r-t.total));$('received').disabled=$('payment').value!=='cash'}
function openCheckout(){if(!state.cart.length)return alert('Cart is empty');$('checkoutMsg').textContent='';$('checkoutModal').classList.remove('hidden');updateTotals()}
async function completeSale(){const btn=$('saleBtn');try{const t=totals();const payment=$('payment').value;const received=payment==='cash'?Math.max(0,num($('received').value)):t.total;if(payment==='cash'&&received+0.0001<t.total)return $('checkoutMsg').textContent='Amount received is less than total.';btn.disabled=true;const d=await api('sale',{method:'POST',body:{items:state.cart.map(i=>({product_id:i.product_id,quantity:i.quantity})),discount:t.dis,tax:t.tax,payment_method:payment,amount_received:received,customer:{name:$('custName').value.trim()||'Walk-in Customer',phone:$('custPhone').value.trim(),address:$('custAddress').value.trim()}}});state.cart=[];['custName','custPhone','custAddress','received'].forEach(x=>$(x).value='');$('discount').value=0;$('tax').value=0;closeModal('checkoutModal');await loadAll();await viewInvoice(d.invoice_id)}catch(e){$('checkoutMsg').textContent=e.message}finally{btn.disabled=false}}
async function loadInvoices(){const d=await api('invoices',{params:{limit:500}});state.invoices=d.invoices;renderInvoices()}
function renderInvoices(){const q=$('invoiceSearch').value.toLowerCase();const arr=state.invoices.filter(i=>(`${i.invoice_no} ${i.customer_name||''} ${i.status}`).toLowerCase().includes(q));$('invoiceTable').innerHTML=arr.map(i=>`<tr><td>${esc(i.invoice_no)}</td><td>${esc(i.customer_name||'Walk-in')}</td><td>${money(i.total)}</td><td>${esc(i.payment_method)}</td><td>${esc(i.status)}</td><td>${new Date(i.created_at).toLocaleString()}</td><td><button class="btn secondary" onclick="viewInvoice(${Number(i.id)})">View</button></td></tr>`).join('')||'<tr><td colspan="7" class="muted">No invoices found.</td></tr>'}
async function viewInvoice(id){const d=await api('invoice',{params:{id}});state.currentInvoice=d.invoice;renderInvoice(d.invoice);const canManage=['super_admin','shop_admin'].includes(state.user.role)&&d.invoice.status==='paid';$('cancelInvoiceBtn').classList.toggle('hidden',!canManage);$('refundInvoiceBtn').classList.toggle('hidden',!canManage);$('invoiceModal').classList.remove('hidden')}
function renderInvoice(i){$('invoicePrint').innerHTML=`<header><h2>${esc(i.shop_name)}</h2><div>${esc(i.slogan||'')}</div><div>${esc(i.customer_address||'')}</div></header><p><b>Invoice:</b> ${esc(i.invoice_no)}<br><b>Date:</b> ${esc(new Date(i.created_at).toLocaleString())}<br><b>Customer:</b> ${esc(i.customer_name||'Walk-in Customer')}<br><b>Phone:</b> ${esc(i.customer_phone||'')}</p><table><thead><tr><th>Item</th><th>Qty</th><th>Unit</th><th>Total</th></tr></thead><tbody>${i.items.map(x=>`<tr><td>${esc(x.product_name)}${x.sku?`<br><small>${esc(x.sku)}</small>`:''}</td><td>${Number(x.quantity)}</td><td>${money(x.unit_price)}</td><td>${money(x.line_total)}</td></tr>`).join('')}</tbody></table><div class="row"><span>Subtotal</span><b>${money(i.subtotal)}</b></div><div class="row"><span>Discount</span><b>${money(i.discount)}</b></div><div class="row"><span>Tax</span><b>${money(i.tax)}</b></div><div class="row" style="font-size:18px;border-top:2px solid #222;padding-top:8px"><b>Total</b><b>${money(i.total)}</b></div><p><b>Payment:</b> ${esc(i.payment_method)}<br><b>Received:</b> ${money(i.amount_received)}<br><b>Change:</b> ${money(i.change_due)}<br><b>Status:</b> ${esc(i.status)}</p>${i.cancellation_reason?`<p><b>Cancellation:</b> ${esc(i.cancellation_reason)}</p>`:''}${i.refund_reason?`<p><b>Refund:</b> ${esc(i.refund_reason)}</p>`:''}<p style="text-align:center">Thank you for your business!</p>`}
async function changeInvoiceStatus(type){if(!state.currentInvoice)return;const reason=prompt(type==='refund'?'Refund reason (optional):':'Cancellation reason (optional):','');if(reason===null)return;try{await api(type==='refund'?'refund_invoice':'cancel_invoice',{method:'POST',body:{id:Number(state.currentInvoice.id),reason}});await viewInvoice(state.currentInvoice.id);await loadAll();alert(type==='refund'?'Invoice refunded and stock restored.':'Invoice cancelled and stock restored.')}catch(e){alert(e.message)}}
function printInvoice(cls){$('invoiceModal').classList.add(cls);window.print();setTimeout(()=>$('invoiceModal').classList.remove(cls),500)}
function downloadInvoice(){const i=state.currentInvoice;if(!i)return;const text=[i.shop_name,i.slogan||'',`Invoice: ${i.invoice_no}`,`Date: ${new Date(i.created_at).toLocaleString()}`,`Customer: ${i.customer_name||'Walk-in Customer'}`,'',...i.items.map(x=>`${x.product_name} x${x.quantity} @ ${Number(x.unit_price).toFixed(2)} = ${Number(x.line_total).toFixed(2)}`),'',`Subtotal: ${i.subtotal}`,`Discount: ${i.discount}`,`Tax: ${i.tax}`,`TOTAL: ${i.total}`,`Payment: ${i.payment_method}`,`Received: ${i.amount_received}`,`Change: ${i.change_due}`,`Status: ${i.status}`].join('\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type:'text/plain'}));a.download=i.invoice_no+'.txt';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
async function loadCustomers(){const d=await api('customers');state.customers=d.customers;$('customerTable').innerHTML=d.customers.map(c=>`<tr><td>${esc(c.name)}</td><td>${esc(c.phone||'')}</td><td>${esc(c.address||'')}</td><td>${new Date(c.created_at).toLocaleDateString()}</td></tr>`).join('')||'<tr><td colspan="4" class="muted">No customers yet.</td></tr>'}
async function loadDashboard(){const d=await api('dashboard');$('sToday').textContent=money(d.today.revenue);$('sTodayCount').textContent=`${d.today.invoices} invoices`;$('sWeek').textContent=money(d.week.revenue);$('sWeekCount').textContent=`${d.week.invoices} invoices`;$('sProducts').textContent=d.products;$('sLow').textContent=d.low_stock;$('dashPayments').innerHTML=d.payments.map(p=>`<div class="row"><span>${esc(p.payment_method)}</span><b>${money(p.total)} <small>(${p.count})</small></b></div>`).join('')||'<span class="muted">No sales today.</span>'}
function renderProductTable(){const q=($('productAdminSearch').value||'').toLowerCase();$('productTable').innerHTML=state.products.filter(p=>(p.name+' '+(p.sku||'')+' '+(p.category||'')).toLowerCase().includes(q)).map(p=>`<tr><td>${esc(p.name)}</td><td>${esc(p.sku||'')}</td><td>${esc(p.category||'')}</td><td>${money(p.selling_price)}</td><td>${money(p.cost_price)}</td><td>${Number(p.stock)} ${Number(p.stock)<=Number(p.low_stock_threshold)?'⚠️':''}</td><td>${Number(p.active)?'<span class="ok-text">Active</span>':'<span class="danger-text">Archived</span>'}</td><td>${state.user.role!=='cashier'?(Number(p.active)?`<button class="btn secondary" onclick="openProduct(${Number(p.id)})">Edit</button> <button class="btn danger" onclick="deleteProduct(${Number(p.id)})">Archive</button>`:`<button class="btn secondary" onclick="restoreProduct(${Number(p.id)})">Restore</button>`):''}</td></tr>`).join('')||'<tr><td colspan="8" class="muted">No products.</td></tr>'}
function openProduct(id=0){const p=state.products.find(x=>Number(x.id)===id);$('productModalTitle').textContent=id?'Edit Product':'New Product';$('pId').value=p?.id||'';$('pName').value=p?.name||'';$('pSku').value=p?.sku||'';$('pCategory').value=p?.category||'';$('pDesc').value=p?.description||'';$('pCost').value=p?.cost_price||0;$('pPrice').value=p?.selling_price||0;$('pStock').value=p?.stock||0;$('pLow').value=p?.low_stock_threshold??5;$('pActive').checked=Number(p?.active??1)===1;$('productMsg').textContent='';$('productModal').classList.remove('hidden')}
async function saveProduct(){try{const stock=Math.max(0,Math.floor(num($('pStock').value)));const low=Math.max(0,Math.floor(num($('pLow').value)));const price=Math.max(0,num($('pPrice').value));const cost=Math.max(0,num($('pCost').value));if(!$('pName').value.trim())throw new Error('Product name is required.');await api('save_product',{method:'POST',body:{id:Number($('pId').value||0),name:$('pName').value,sku:$('pSku').value,category:$('pCategory').value,description:$('pDesc').value,cost_price:cost,selling_price:price,stock,low_stock_threshold:low,active:$('pActive').checked}});closeModal('productModal');await loadProducts()}catch(e){$('productMsg').textContent=e.message}}
async function deleteProduct(id){if(!confirm('Archive this product? Existing invoices remain safe.'))return;try{await api('delete_product',{method:'POST',body:{id}});await loadProducts()}catch(e){alert(e.message)}}async function restoreProduct(id){try{await api('restore_product',{method:'POST',body:{id}});await loadProducts()}catch(e){alert(e.message)}}
async function loadUsers(){if(state.user.role==='cashier')return;const d=await api('users');state.users=d.users;$('userTable').innerHTML=d.users.map(u=>`<tr><td>${esc(u.name)}</td><td>${esc(u.email)}</td><td>${esc(u.role)}</td><td>${Number(u.active)?'<span class="ok-text">Yes</span>':'<span class="danger-text">No</span>'}</td><td>${u.last_login_at?esc(new Date(u.last_login_at).toLocaleString()):'Never'}</td><td><button class="btn secondary" onclick="openUser(${Number(u.id)})">Edit</button></td></tr>`).join('')||'<tr><td colspan="6" class="muted">No users.</td></tr>'}
function openUser(id=0){const u=state.users.find(x=>Number(x.id)===id);$('userModalTitle').textContent=id?'Edit User':'New User';$('uId').value=u?.id||'';$('uName').value=u?.name||'';$('uEmail').value=u?.email||'';$('uRole').value=u?.role||'cashier';$('uPassword').value='';$('uPassword').placeholder=id?'Leave blank to keep password':'Password (10+ chars)';$('uActive').checked=Number(u?.active??1)===1;$('userMsg').textContent='';$('userModal').classList.remove('hidden')}
async function saveUser(){try{await api('save_user',{method:'POST',body:{id:Number($('uId').value||0),name:$('uName').value,email:$('uEmail').value,role:$('uRole').value,password:$('uPassword').value,active:$('uActive').checked}});closeModal('userModal');await loadUsers()}catch(e){$('userMsg').textContent=e.message}}
function openShopModal(id=0){if(state.user.role!=='super_admin')return;const s=state.shops.find(x=>Number(x.id)===id);$('shopModalTitle').textContent=id?'Edit Shop':'Create Shop';$('sId').value=s?.id||'';$('sName').value=s?.name||'';$('sCurrency').value=s?.currency||'Rs.';$('sPhone').value=s?.phone||'';$('sPlanExpiry').value=s?.plan_expires_at||'';$('sSlogan').value=s?.slogan||'';$('sAddress').value=s?.address||'';$('sPlan').value=s?.plan||'starter';$('sStatus').value=s?.status||'active';['sAdminName','sAdminEmail','sAdminPassword'].forEach(x=>$(x).value='');$('shopMsg').textContent='';$('shopModal').classList.remove('hidden')}
async function saveShop(){try{const id=Number($('sId').value||0);if(!id&&(!$('sAdminEmail').value||!$('sAdminPassword').value))throw new Error('New shops require an admin email and password.');const body={id,name:$('sName').value,currency:$('sCurrency').value,phone:$('sPhone').value,plan_expires_at:$('sPlanExpiry').value,slogan:$('sSlogan').value,address:$('sAddress').value,plan:$('sPlan').value,status:$('sStatus').value};let action='update_shop';if(!id){Object.assign(body,{email:$('sAdminEmail').value,password:$('sAdminPassword').value,admin_name:$('sAdminName').value});action='create_shop'}await api(action,{method:'POST',body});closeModal('shopModal');state.shop=null;await loadAll()}catch(e){$('shopMsg').textContent=e.message}}
async function loadReports(){try{const d=await api('reports',{params:{from:$('reportFrom').value,to:$('reportTo').value}});$('rRevenue').textContent=money(d.summary.revenue);$('rInvoices').textContent=d.summary.invoices;$('rTax').textContent=money(d.summary.tax);$('rDiscounts').textContent=money(d.summary.discounts);$('topProducts').innerHTML=d.top_products.map(p=>`<div class="row"><span>${esc(p.product_name)}<br><small>${p.units} units</small></span><b>${money(p.sales)}</b></div>`).join('')||'<span class="muted">No sales.</span>';$('paymentBreakdown').innerHTML=d.payments.map(p=>`<div class="row"><span>${esc(p.payment_method)}</span><b>${money(p.total)}<br><small>${p.invoices} invoices</small></b></div>`).join('')||'<span class="muted">No payments.</span>'}catch(e){alert(e.message)}}
function exportInvoicesCsv(){const rows=[['Invoice','Customer','Total','Payment','Status','Date']].concat(state.invoices.map(i=>[i.invoice_no,i.customer_name||'Walk-in',Number(i.total).toFixed(2),i.payment_method,i.status,i.created_at]));const csv=rows.map(r=>r.map(csvCell).join(',')).join('\r\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.download='invoices-'+new Date().toISOString().slice(0,10)+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}function csvCell(v){const s=String(v??'');return /[",\r\n]/.test(s)?'"'+s.replace(/"/g,'""')+'"':s}
async function loadAudit(){if(state.user.role==='cashier')return;const d=await api('audit',{params:{limit:300}});$('auditTable').innerHTML=d.logs.map(l=>`<tr><td>${esc(new Date(l.created_at).toLocaleString())}</td><td>${esc(l.user_name||'System')}</td><td>${esc(l.action)}</td><td>${esc(l.entity_type||'')} ${l.entity_id?esc(l.entity_id):''}</td><td>${esc(l.details||'')}</td><td>${esc(l.ip_address||'')}</td></tr>`).join('')||'<tr><td colspan="6" class="muted">No audit entries.</td></tr>'}
$('passwordForm').addEventListener('submit',async e=>{e.preventDefault();$('passwordMsg').textContent='';try{await api('change_password',{method:'POST',body:{current_password:$('oldPassword').value,new_password:$('newPassword').value}});$('oldPassword').value='';$('newPassword').value='';$('passwordMsg').textContent='Password changed successfully.';$('passwordMsg').className='ok-text'}catch(e){$('passwordMsg').textContent=e.message;$('passwordMsg').className='danger-text'}});
$('productSearch').addEventListener('input',renderProducts);$('productAdminSearch').addEventListener('input',renderProductTable);$('invoiceSearch').addEventListener('input',renderInvoices);$('discount').addEventListener('input',updateTotals);$('tax').addEventListener('input',updateTotals);$('received').addEventListener('input',updateTotals);$('payment').addEventListener('change',updateTotals);
document.querySelectorAll('.tab').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('.tab').forEach(x=>x.classList.remove('active'));b.classList.add('active');document.querySelectorAll('section[id^="tab-"]').forEach(s=>s.classList.add('hidden'));$('tab-'+b.dataset.tab).classList.remove('hidden');if(b.dataset.tab==='reports'){const d=new Date();$('reportTo').value=d.toISOString().slice(0,10);const f=new Date(Date.now()-29*86400000);$('reportFrom').value=f.toISOString().slice(0,10);loadReports()}}));
function closeModal(id){$(id).classList.add('hidden')}
window.addEventListener('keydown',e=>{if(e.key==='Escape')document.querySelectorAll('.modal').forEach(m=>m.classList.add('hidden'))});
boot();
</script></body></html>
